// block_store.cpp - a small block store with checksummed records.
#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <map>
#include <memory>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

namespace store {

constexpr std::size_t kBlockSize = 4096;
constexpr std::size_t kHeaderSize = 16;
constexpr std::uint32_t kMagic = 0x5354524Au;

struct Header {
    std::uint32_t magic;
    std::uint32_t length;
    std::uint64_t id;
};

static_assert(sizeof(Header) == kHeaderSize, "header layout");

std::uint32_t compute_checksum(const std::uint8_t* data, std::size_t size) {
    std::uint32_t a = 1;
    std::uint32_t b = 0;
    for (std::size_t i = 0; i < size; ++i) {
        a = (a + data[i]) % 65521u;
        b = (b + a) % 65521u;
    }
    return (b << 16) | a;
}

class Block {
public:
    Block(std::uint64_t id, std::size_t capacity)
        : id_(id), bytes_(capacity, 0), used_(0) {}

    std::uint64_t id() const { return id_; }
    std::size_t used() const { return used_; }
    std::size_t capacity() const { return bytes_.size(); }
    bool empty() const { return used_ == 0; }

    bool fits(std::size_t size) const {
        return used_ + kHeaderSize + size <= bytes_.size();
    }

    void append(const std::uint8_t* data, std::size_t size) {
        if (!fits(size)) {
            throw std::length_error("block is full");
        }
        Header h{kMagic, static_cast<std::uint32_t>(size), id_};
        std::memcpy(bytes_.data() + used_, &h, kHeaderSize);
        std::memcpy(bytes_.data() + used_ + kHeaderSize, data, size);
        used_ += kHeaderSize + size;
    }

    std::uint32_t seal() {
        std::uint32_t sum = compute_checksum(bytes_.data(), used_);
        sealed_ = sum;
        return sum;
    }

    bool verify() const {
        if (!sealed_) {
            return false;
        }
        return compute_checksum(bytes_.data(), used_) == *sealed_;
    }

    const std::uint8_t* data() const { return bytes_.data(); }

private:
    std::uint64_t id_;
    std::vector<std::uint8_t> bytes_;
    std::size_t used_;
    std::unique_ptr<std::uint32_t> sealed_;
};

class BlockStore {
public:
    explicit BlockStore(std::size_t block_size = kBlockSize)
        : block_size_(block_size), next_id_(1) {
        if (block_size_ <= kHeaderSize) {
            throw std::invalid_argument("block size too small");
        }
    }

    std::uint64_t put(const std::string& payload) {
        return put(reinterpret_cast<const std::uint8_t*>(payload.data()), payload.size());
    }

    std::uint64_t put(const std::uint8_t* data, std::size_t size) {
        if (size + kHeaderSize > block_size_) {
            throw std::length_error("record larger than a block");
        }
        Block& block = writable_block(size);
        block.append(data, size);
        index_[block.id()] = last_index();
        ++records_;
        return block.id();
    }

    bool get(std::uint64_t record, std::string& out) const {
        auto it = index_.find(record);
        if (it == index_.end()) {
            return false;
        }
        const Block& block = blocks_[it->second];
        std::size_t offset = 0;
        while (offset + kHeaderSize <= block.used()) {
            Header h{};
            std::memcpy(&h, block.data() + offset, kHeaderSize);
            if (h.magic != kMagic) {
                throw std::runtime_error("bad record magic");
            }
            if (h.id == record) {
                out.assign(reinterpret_cast<const char*>(block.data() + offset + kHeaderSize), h.length);
                return true;
            }
            offset += kHeaderSize + h.length;
        }
        return false;
    }

    void seal_all() {
        for (auto& block : blocks_) {
            if (!block.empty()) {
                block.seal();
            }
        }
    }

    std::size_t verify_all() const {
        std::size_t bad = 0;
        for (const auto& block : blocks_) {
            if (!block.empty() && !block.verify()) {
                ++bad;
            }
        }
        return bad;
    }

    std::size_t block_count() const { return blocks_.size(); }
    std::size_t record_count() const { return records_; }

    std::uint32_t digest() const {
        std::uint32_t acc = 0;
        for (const auto& block : blocks_) {
            acc ^= compute_checksum(block.data(), block.used());
        }
        return acc;
    }

private:
    Block& writable_block(std::size_t size) {
        if (blocks_.empty() || !blocks_.back().fits(size)) {
            blocks_.emplace_back(next_id_++, block_size_);
        }
        return blocks_.back();
    }

    std::size_t last_index() const { return blocks_.size() - 1; }

    std::size_t block_size_;
    std::uint64_t next_id_;
    std::size_t records_ = 0;
    std::vector<Block> blocks_;
    std::map<std::uint64_t, std::size_t> index_;
};

std::string describe(const BlockStore& store) {
    std::string text = "blocks=" + std::to_string(store.block_count());
    text += " records=" + std::to_string(store.record_count());
    text += " digest=" + std::to_string(store.digest());
    return text;
}

std::vector<std::uint32_t> checksums(const std::vector<std::string>& payloads) {
    std::vector<std::uint32_t> out;
    out.reserve(payloads.size());
    for (const auto& p : payloads) {
        out.push_back(compute_checksum(reinterpret_cast<const std::uint8_t*>(p.data()), p.size()));
    }
    return out;
}

bool same_checksums(const std::vector<std::string>& a, const std::vector<std::string>& b) {
    if (a.size() != b.size()) {
        return false;
    }
    return checksums(a) == checksums(b);
}

std::vector<std::string> split_records(const std::string& text, std::size_t max_size) {
    std::vector<std::string> parts;
    std::size_t start = 0;
    while (start < text.size()) {
        std::size_t len = std::min(max_size, text.size() - start);
        parts.push_back(text.substr(start, len));
        start += len;
    }
    return parts;
}

std::string join_records(const std::vector<std::string>& parts) {
    std::string out;
    for (const auto& p : parts) {
        out += p;
    }
    return out;
}

struct Stats {
    std::size_t puts = 0;
    std::size_t gets = 0;
    std::size_t misses = 0;
    std::size_t bytes = 0;
};

class Instrumented {
public:
    explicit Instrumented(BlockStore& inner) : inner_(inner) {}

    std::uint64_t put(const std::string& payload) {
        ++stats_.puts;
        stats_.bytes += payload.size();
        return inner_.put(payload);
    }

    bool get(std::uint64_t id, std::string& out) {
        ++stats_.gets;
        bool found = inner_.get(id, out);
        if (!found) {
            ++stats_.misses;
        }
        return found;
    }

    const Stats& stats() const { return stats_; }

private:
    BlockStore& inner_;
    Stats stats_;
};

std::size_t count_empty(const std::vector<Block>& blocks) {
    return static_cast<std::size_t>(std::count_if(blocks.begin(), blocks.end(),
                                                  [](const Block& b) { return b.empty(); }));
}

}  // namespace store
